import { useRef, useState } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLE_OPTIONS = [
  { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
  { value: 'editor', label: 'Редактор', meta: 'Правит содержимое' },
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только просмотр' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [sending, setSending] = useState(false);
  const [sentTo, setSentTo] = useState<string | null>(null);

  const emailRef = useRef<HTMLInputElement>(null);
  const alertCloseRef = useRef<HTMLButtonElement>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValid ? 'Укажите адрес вида name@example.com' : undefined;

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid || sending) {
      emailRef.current?.focus();
      return;
    }
    setSending(true);
    try {
      setSentTo(email.trim());
      setEmail('');
      setTouched(false);
    } finally {
      setSending(false);
    }
  };

  const dismiss = () => {
    setSentTo(null);
    emailRef.current?.focus();
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        maxWidth: 420,
        padding: 20,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      {sentTo !== null && (
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <JxAlert intent="success" title="Приглашение отправлено" role="status">
              <span style={{ wordBreak: 'break-word' }}>
                {notify ? `Мы написали на ${sentTo}.` : `Участник ${sentTo} добавлен без уведомления.`}
              </span>
            </JxAlert>
          </div>
          <JxButton
            ref={alertCloseRef}
            variant="ghost"
            size="sm"
            iconOnly
            aria-label="Закрыть сообщение"
            onClick={dismiss}
          >
            ×
          </JxButton>
        </div>
      )}

      <JxInputField
        ref={emailRef}
        label="Почта участника"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        helperText="Пригласим одного человека — по одному адресу за раз."
        errorText={errorText}
      />

      <JxSelect
        label="Роль в команде"
        placeholder="Выберите роль"
        options={ROLE_OPTIONS}
        value={role}
        onValueChange={setRole}
      />

      <JxSwitch
        label="Отправить уведомление на почту"
        name="notify"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <JxButton type="submit" variant="primary" disabled={!isValid || sending}>
        {sending ? 'Отправляем…' : 'Отправить приглашение'}
      </JxButton>
    </form>
  );
}

